1	import * as THREE from "three";
2	import { fetchWorksList } from "../../../api/getWork.js";
3	import type { WorkApiItem } from "../../../types/work.types.js";
4	import {
5	  type ProofRotationStrategy,
6	  ScrollAcceleratingRotation,
7	  DEFAULT_SCROLL_ACCELERATING_CONFIG,
8	} from "./ProofRotationStrategy.js";
9	import atmosphereVertexShader from "../../../../shaders/earth/vertex.glsl?raw";
10	
11	const PLANET_ATMOSPHERE_FRAGMENT = `
12	varying vec3 vNormal;
13	varying vec3 eyeVector;
14	uniform float atmOpacity;
15	uniform float atmPowFactor;
16	uniform float atmMultiplier;
17	uniform vec3 atmColor;
18	
19	void main() {
20	    float dotP = max(0.0, dot(vNormal, eyeVector));
21	    float factor = pow(dotP, atmPowFactor) * atmMultiplier;
22	    vec3 rimColor = mix(atmColor * 0.82, vec3(1.0), 0.28 + dotP * 0.18);
23	    gl_FragColor = vec4(rimColor, atmOpacity) * factor;
24	}
25	`;
26	
27	const CARD_HEIGHT = 3.4;
28	const CARD_WIDTH = CARD_HEIGHT * (16 / 9);
29	const MAX_PROOF_IMAGES = 12;
30	const FALLBACK_COUNT = 8;
31	const PLANET_RADIUS = 8.0;
32	const CARD_RING_MIN_RADIUS = PLANET_RADIUS * 1.55;
33	const FALLBACK_COLORS = [
34	  0x6644aa, 0x4488bb, 0x44aacc, 0x228866, 0x886622, 0xaa4466, 0x664488, 0x4466aa,
35	] as const;
36	
37	function computeRadius(cardCount: number): number {
38	  const minArc = CARD_WIDTH * 1.15;
39	  return Math.max(CARD_RING_MIN_RADIUS, (minArc * cardCount) / (2 * Math.PI));
40	}
41	
42	/**
43	 * Creates a PlaneGeometry whose vertices are bent cylindrically around the Y-axis,
44	 * so the card's edges curve inward toward the planet (local -Z = radially inward).
45	 * Each vertex at local x=lx is moved to arc position on a cylinder of curveRadius:
46	 *   newX = curveRadius * sin(lx / curveRadius)
47	 *   newZ = -curveRadius * (1 - cos(lx / curveRadius))   ← negative = toward planet
48	 */
49	function createCurvedCardGeometry(
50	  width: number,
51	  height: number,
52	  curveRadius: number,
53	): THREE.BufferGeometry {
54	  const geo = new THREE.PlaneGeometry(width, height, 20, 1);
55	  const pos = geo.attributes.position as THREE.BufferAttribute;
56	  for (let i = 0; i < pos.count; i++) {
57	    const lx = pos.getX(i);
58	    const dAngle = lx / curveRadius;
59	    pos.setX(i, curveRadius * Math.sin(dAngle));
60	    pos.setZ(i, -curveRadius * (1.0 - Math.cos(dAngle)));
61	  }
62	  pos.needsUpdate = true;
63	  geo.computeVertexNormals();
64	  return geo;
65	}
66	
67	function loadImageTexture(
68	  loader: THREE.TextureLoader,
69	  url: string,
70	): Promise<THREE.Texture | null> {
71	  return new Promise((resolve) => {
72	    loader.load(
73	      url,
74	      (texture) => {
75	        texture.minFilter = THREE.LinearFilter;
76	        texture.generateMipmaps = false;
77	        resolve(texture);
78	      },
79	      undefined,
80	      () => resolve(null),
81	    );
82	  });
83	}
84	
85	function createCardMaterial(
86	  texture: THREE.Texture | null,
87	  color: number,
88	): THREE.MeshBasicMaterial {
89	  const mat = new THREE.MeshBasicMaterial({
90	    map: texture ?? null,
91	    color: texture ? 0xffffff : color,
92	    side: THREE.DoubleSide,
93	  });
94	
95	  if (texture) {
96	    // Flip UV.x on back face so back-side texture is not mirrored
97	    mat.onBeforeCompile = (shader) => {
98	      shader.fragmentShader = shader.fragmentShader.replace(
99	        "vec4 sampledDiffuseColor = texture2D( map, vMapUv );",
100	        `vec2 _uv = gl_FrontFacing ? vMapUv : vec2(1.0 - vMapUv.x, vMapUv.y);
101	        vec4 sampledDiffuseColor = texture2D( map, _uv );`,
102	      );
103	    };
104	    mat.customProgramCacheKey = () => "proof-card-textured";
105	    mat.needsUpdate = true;
106	  }
107	
108	  return mat;
109	}
110	
111	function selectProofItems(items: WorkApiItem[], max: number): WorkApiItem[] {
112	  const awardedVideo = items.filter((i) => i.isAwarded && i.thumbnailVideo);
113	  const awardedImage = items.filter((i) => i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
114	  const otherVideo   = items.filter((i) => !i.isAwarded && i.thumbnailVideo);
115	  const otherImage   = items.filter((i) => !i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
116	
117	  const result: WorkApiItem[] = [...awardedVideo];
118	  if (result.length < max) result.push(...awardedImage);
119	  if (result.length < max) result.push(...otherVideo);
120	  if (result.length < max) result.push(...otherImage);
121	  return result.slice(0, max);
122	}
123	
124	export class AboutProofRenderer {
125	  private _renderer: THREE.WebGLRenderer | null = null;
126	  private _scene: THREE.Scene | null = null;
127	  private _camera: THREE.PerspectiveCamera | null = null;
128	  private _group: THREE.Group | null = null;
129	  private _planetGroup: THREE.Group | null = null;
130	  private _geometries: THREE.BufferGeometry[] = [];
131	  private _materials: THREE.Material[] = [];
132	  private _textures: THREE.Texture[] = [];
133	  private _videoElements: HTMLVideoElement[] = [];
134	  private _rafId: number | null = null;
135	  private _resizeObserver: ResizeObserver | null = null;
136	  private _intersectionObserver: IntersectionObserver | null = null;
137	  private _rendering = false;
138	  private _disposed = false;
139	  private _canvas: HTMLCanvasElement | null = null;
140	  private _scrollProgress = 0;
141	  private _rotationStrategy: ProofRotationStrategy;
142	
143	  constructor(rotationStrategy?: ProofRotationStrategy) {
144	    this._rotationStrategy =
145	      rotationStrategy ?? new ScrollAcceleratingRotation(DEFAULT_SCROLL_ACCELERATING_CONFIG);
146	  }
147	
148	  setScrollProgress(progress: number): void {
149	    const prev = this._scrollProgress;
150	    this._scrollProgress = Math.max(0, Math.min(1, progress));
151	    this._rotationStrategy.feed(this._scrollProgress, Math.abs(this._scrollProgress - prev));
152	  }
153	
154	  async init(canvas: HTMLCanvasElement): Promise<void> {
155	    this._canvas = canvas;
156	
157	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
158	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
159	    renderer.setClearAlpha(0);
160	    this._renderer = renderer;
161	
162	    const scene = new THREE.Scene();
163	    this._scene = scene;
164	
165	    const w = Math.max(canvas.clientWidth, 1);
166	    const h = Math.max(canvas.clientHeight, 1);
167	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
168	    camera.position.set(0, 3, 22);
169	    camera.lookAt(0, 0, 0);
170	    this._camera = camera;
171	
172	    scene.add(new THREE.AmbientLight(0x8ea8d8, 0.28));
173	
174	    const keyLight = new THREE.SpotLight(0xdfe8ff, 2.8);
175	    keyLight.position.set(14, 20, 10);
176	    keyLight.angle = 0.30;
177	    keyLight.penumbra = 0.52;
178	    keyLight.decay = 1.35;
179	    keyLight.distance = 60;
180	    scene.add(keyLight);
181	    scene.add(keyLight.target);
182	
183	    const fillLight = new THREE.DirectionalLight(0xa9c2ff, 0.55);
184	    fillLight.position.set(-20, 14, 20);
185	    scene.add(fillLight);
186	
187	    const rimLight = new THREE.SpotLight(0x9fb7ff, 0.20);
188	    rimLight.position.set(-10, 8, -14);
189	    rimLight.angle = 0.20;
190	    rimLight.penumbra = 0.90;
191	    rimLight.decay = 1.4;
192	    rimLight.distance = 45;
193	    scene.add(rimLight);
194	    scene.add(rimLight.target);
195	
196	    const group = new THREE.Group();
197	    this._group = group;
198	    scene.add(group);
199	
200	    // Fetch works and planet textures in parallel
201	    const [worksResult, planetGroup] = await Promise.all([
202	      fetchWorksList(0, MAX_PROOF_IMAGES, null, undefined, true).catch(() => null),
203	      this._buildPlanet(),
204	    ]);
205	
206	    if (this._disposed) return;
207	
208	    if (planetGroup) {
209	      this._planetGroup = planetGroup;
210	      scene.add(planetGroup);
211	    }
212	
213	    const items = worksResult ? selectProofItems(worksResult.items, MAX_PROOF_IMAGES) : [];
214	
215	    if (items.length > 0) {
216	      const loader = new THREE.TextureLoader();
217	      const textures = await Promise.all(
218	        items.map((item) => this._loadItemMedia(loader, item)),
219	      );
220	      if (this._disposed) return;
221	      const radius = computeRadius(textures.length);
222	      const sharedGeo = createCurvedCardGeometry(CARD_WIDTH, CARD_HEIGHT, radius);
223	      this._geometries.push(sharedGeo);
224	      textures.forEach((texture, i) => {
225	        if (texture) this._textures.push(texture);
226	        this._addCard(group, i, textures.length, texture, radius, sharedGeo);
227	      });
228	    } else {
229	      const radius = computeRadius(FALLBACK_COUNT);
230	      const sharedGeo = createCurvedCardGeometry(CARD_WIDTH, CARD_HEIGHT, radius);
231	      this._geometries.push(sharedGeo);
232	      for (let i = 0; i < FALLBACK_COUNT; i++) {
233	        this._addCard(group, i, FALLBACK_COUNT, null, radius, sharedGeo);
234	      }
235	    }
236	
237	    this._syncSize();
238	    this._observeResize();
239	    this._observeVisibility();
240	  }
241	
242	  dispose(): void {
243	    this._disposed = true;
244	    this._stopRaf();
245	
246	    this._resizeObserver?.disconnect();
247	    this._resizeObserver = null;
248	
249	    this._intersectionObserver?.disconnect();
250	    this._intersectionObserver = null;
251	
252	    this._geometries.forEach((g) => g.dispose());
253	    this._geometries = [];
254	
255	    this._materials.forEach((m) => m.dispose());
256	    this._materials = [];
257	
258	    this._textures.forEach((t) => t.dispose());
259	    this._textures = [];
260	
261	    this._videoElements.forEach((v) => {
262	      v.pause();
263	      v.src = "";
264	      v.load();
265	    });
266	    this._videoElements = [];
267	
268	    this._renderer?.dispose();
269	    this._renderer?.forceContextLoss();
270	    this._renderer = null;
271	    this._scene = null;
272	    this._camera = null;
273	    this._group = null;
274	    this._planetGroup = null;
275	    this._canvas = null;
276	  }
277	
278	  private async _buildPlanet(): Promise<THREE.Group | null> {
279	    const loader = new THREE.TextureLoader();
280	    try {
281	      const [dayMap, bumpMap] = await Promise.all([
282	        new Promise<THREE.Texture>((res, rej) =>
283	          loader.load("/resource/images/texture/moon/moonmap4k.jpg", res, undefined, rej),
284	        ),
285	        new Promise<THREE.Texture>((res, rej) =>
286	          loader.load("/resource/images/texture/moon/moonbump4k.jpg", res, undefined, rej),
287	        ),
288	      ]);
289	
290	      if (this._disposed) {
291	        dayMap.dispose();
292	        bumpMap.dispose();
293	        return null;
294	      }
295	
296	      dayMap.colorSpace = THREE.SRGBColorSpace;
297	      this._textures.push(dayMap, bumpMap);
298	
299	      const geo = new THREE.SphereGeometry(PLANET_RADIUS, 32, 24);
300	      const mat = new THREE.MeshStandardMaterial({
301	        map: dayMap,
302	        bumpMap,
303	        bumpScale: 0.022,
304	        roughness: 0.35,
305	        metalness: 0.05,
306	      });
307	      this._geometries.push(geo);
308	      this._materials.push(mat);
309	      const mesh = new THREE.Mesh(geo, mat);
310	
311	      const atmGeo = new THREE.SphereGeometry(PLANET_RADIUS * 1.16, 32, 24);
312	      const atmMat = new THREE.ShaderMaterial({
313	        vertexShader: atmosphereVertexShader as string,
314	        fragmentShader: PLANET_ATMOSPHERE_FRAGMENT,
315	        uniforms: {
316	          atmOpacity: { value: 0.58 },
317	          atmPowFactor: { value: 4.3 },
318	          atmMultiplier: { value: 8.4 },
319	          atmColor: { value: new THREE.Color(0.92, 0.96, 1.0) },
320	        },
321	        blending: THREE.AdditiveBlending,
322	        side: THREE.BackSide,
323	        transparent: true,
324	        depthWrite: false,
325	      });
326	      this._geometries.push(atmGeo);
327	      this._materials.push(atmMat);
328	      const atmMesh = new THREE.Mesh(atmGeo, atmMat);
329	
330	      const group = new THREE.Group();
331	      group.add(mesh);
332	      group.add(atmMesh);
333	      return group;
334	    } catch {
335	      return null;
336	    }
337	  }
338	
339	  private _createVideoElement(url: string): HTMLVideoElement {
340	    const video = document.createElement("video");
341	    video.src = url;
342	    video.loop = true;
343	    video.muted = true;
344	    video.playsInline = true;
345	    video.crossOrigin = "anonymous";
346	    void video.play();
347	    this._videoElements.push(video);
348	    return video;
349	  }
350	
351	  private _createVideoTexture(video: HTMLVideoElement): THREE.VideoTexture {
352	    const texture = new THREE.VideoTexture(video);
353	    texture.minFilter = THREE.LinearFilter;
354	    texture.magFilter = THREE.LinearFilter;
355	    texture.generateMipmaps = false;
356	    return texture;
357	  }
358	
359	  private async _loadItemMedia(
360	    loader: THREE.TextureLoader,
361	    item: WorkApiItem,
362	  ): Promise<THREE.Texture | null> {
363	    if (item.thumbnailVideo) {
364	      const video = this._createVideoElement(item.thumbnailVideo);
365	      return this._createVideoTexture(video);
366	    }
367	    const imageUrl = item.thumbnailImage;
368	    if (imageUrl) {
369	      return loadImageTexture(loader, imageUrl);
370	    }
371	    return null;
372	  }
373	
374	  private _addCard(
375	    group: THREE.Group,
376	    index: number,
377	    total: number,
378	    texture: THREE.Texture | null,
379	    radius: number,
380	    sharedGeo: THREE.BufferGeometry,
381	  ): void {
382	    const angle = (index / total) * Math.PI * 2;
383	    const x = radius * Math.cos(angle);
384	    const z = radius * Math.sin(angle);
385	
386	    const mat = createCardMaterial(
387	      texture,
388	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
389	    );
390	    this._materials.push(mat);
391	
392	    const mesh = new THREE.Mesh(sharedGeo, mat);
393	    mesh.position.set(x, 0, z);
394	    // rotation.y so the front face (+Z normal) points radially outward from center
395	    mesh.rotation.y = Math.PI / 2 - angle;
396	    group.add(mesh);
397	  }
398	
399	  private readonly _tick = (): void => {
400	    if (this._disposed || !this._rendering) return;
401	    const p = this._scrollProgress;
402	    const speed = this._rotationStrategy.next();
403	    if (this._group) this._group.rotation.y += speed;
404	    // Planet counter-rotates slowly, independent of card ring
405	    if (this._planetGroup) this._planetGroup.rotation.y += 0.0003;
406	    if (this._camera) {
407	      this._camera.position.y = 3 - p * 3;
408	      this._camera.lookAt(0, 0, 0);
409	    }
410	    if (this._renderer && this._scene && this._camera) {
411	      this._renderer.render(this._scene, this._camera);
412	    }
413	    this._rafId = requestAnimationFrame(this._tick);
414	  };
415	
416	  private _startRaf(): void {
417	    if (this._rafId !== null || this._disposed) return;
418	    this._rendering = true;
419	    this._rafId = requestAnimationFrame(this._tick);
420	  }
421	
422	  private _stopRaf(): void {
423	    this._rendering = false;
424	    if (this._rafId !== null) {
425	      cancelAnimationFrame(this._rafId);
426	      this._rafId = null;
427	    }
428	  }
429	
430	  private _syncSize(): void {
431	    const canvas = this._canvas;
432	    const renderer = this._renderer;
433	    const camera = this._camera;
434	    if (!canvas || !renderer || !camera) return;
435	    const w = canvas.clientWidth;
436	    const h = canvas.clientHeight;
437	    if (w <= 0 || h <= 0) return;
438	    renderer.setSize(w, h, false);
439	    camera.aspect = w / h;
440	    camera.updateProjectionMatrix();
441	  }
442	
443	  private _observeResize(): void {
444	    if (!this._canvas) return;
445	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
446	    this._resizeObserver.observe(this._canvas);
447	  }
448	
449	  private _observeVisibility(): void {
450	    if (!this._canvas) return;
451	    this._intersectionObserver = new IntersectionObserver(
452	      (entries) => {
453	        if (entries[0]?.isIntersecting) {
454	          this._startRaf();
455	        } else {
456	          this._stopRaf();
457	        }
458	      },
459	      { threshold: 0 },
460	    );
461	    this._intersectionObserver.observe(this._canvas);
462	  }
463	}
